import json
from pathlib import Path
import sys

# 将项目根目录加入路径（根据你的实际结构调整 parents 数字）
PROJECT_ROOT = Path(__file__).resolve().parents[3]  # 假设根目录是 server 上一级
sys.path.insert(0, str(PROJECT_ROOT))

# 现在安全导入
from src.libraries.checkin import tools


with open(tools.USER_PATH,encoding="utf-8") as f:
    info=json.load(f)

size=[]
labels=[]
for u in info:
    user=tools.User(u)
    if user.data.getBytes()==0:
        continue
    size.append(user.data.getBytes())
    labels.append(user.nickname)
    del user

print(size)
print(labels)
